-- @generated by test/native_api_parity/generate_callin_trace.py; do not edit.
-- This gadget records the Lua side of shared engine callins and returns
-- the same neutral/default values as the C++ Lua implementation.

function gadget:GetInfo()
	return {
		name = "Native API Callin Parity Trace",
		desc = "Traces shared engine-to-Lua/native callins",
		author = "Spring",
		layer = 1000000,
		enabled = true,
	}
end

local Common = VFS.Include("LuaRules/Utilities/native_api_parity_common.lua")
local synced = gadgetHandler:IsSyncedCode()
local outputStream = "callin_lua"

local function roundNumber(value)
	return math.floor(value * 100000 + 0.5) / 100000
end

local function normalize(value, depth)
	local valueType = type(value)
	if valueType == "nil" then return { type = "nil" } end
	if valueType == "number" then return roundNumber(value) end
	if valueType == "boolean" or valueType == "string" then return value end
	if valueType ~= "table" then return valueType end
	if (depth or 0) >= 5 then return { type = "table" } end
	local result = {}
	for key, item in pairs(value) do
		result[#result + 1] = { key = normalize(key, (depth or 0) + 1), value = normalize(item, (depth or 0) + 1) }
	end
	table.sort(result, function(a, b) return Common.encode(a.key) .. Common.encode(a.value) < Common.encode(b.key) .. Common.encode(b.value) end)
	return result
end

local function pack(...)
	local result = { n = select("#", ...) }
	for index = 1, result.n do
		result[index] = select(index, ...)
	end
	return result
end

local function unpackn(values)
	return unpack(values, 1, values.n)
end

local function forward(encoded)
	if Script.LuaUI and Script.LuaUI.NativeApiParityResult then
		Script.LuaUI.NativeApiParityResult(outputStream, encoded)
	end
end

local function trace(name, results, ...)
	local args = pack(...)
	local normalized = {}
	for index = 1, args.n do
		normalized[index] = normalize(args[index], 0)
	end
	local normalizedResults = {}
	for index = 1, results.n do
		normalizedResults[index] = normalize(results[index], 0)
	end
	local payload = {
		context = synced and "synced_gadget" or "unsynced_gadget",
		name = name,
		arity = args.n,
		args = normalized,
		resultArity = results.n,
		results = normalizedResults,
	}
	local encoded = Common.encode(payload)
	if synced then
		SendToUnsynced("native_api_callin_trace", encoded)
	else
		forward(encoded)
	end
end

local function traceCallin(name, ...)
	local args = pack(...)
	local results
	if name == "AllowUnitCreation" then
		results = pack(true, true)
	elseif name == "AllowWeaponTarget" then
		results = pack(true, args[5] or 1.0)
	elseif name == "UnitPreDamaged" or name == "FeaturePreDamaged" then
		results = pack(args[4], 1.0)
	elseif name == "MousePress" then
		results = pack(Common.mode() ~= "native")
	elseif name == "AllowWeaponTargetCheck" then
		results = pack(-1)
	elseif name == "DefaultCommand" or name == "GetTooltip" or name == "WorldTooltip" then
		results = pack(nil)
	else
		local default = {
		["AddConsoleLine"] = {false},
		["AllowBuilderHoldFire"] = {true},
		["AllowCommand"] = {true},
		["AllowDirectUnitControl"] = {true},
		["AllowFeatureBuildStep"] = {true},
		["AllowFeatureCreation"] = {true},
		["AllowResourceLevel"] = {true},
		["AllowResourceTransfer"] = {true},
		["AllowStartPosition"] = {true},
		["AllowUnitBuildStep"] = {true},
		["AllowUnitCaptureStep"] = {true},
		["AllowUnitCloak"] = {true},
		["AllowUnitDecloak"] = {true},
		["AllowUnitKamikaze"] = {true},
		["AllowUnitTransfer"] = {true},
		["AllowUnitTransport"] = {true},
		["AllowUnitTransportLoad"] = {true},
		["AllowUnitTransportUnload"] = {true},
		["AllowWeaponInterceptTarget"] = {true},
		["CommandFallback"] = {false},
		["CommandNotify"] = {false},
		["DrawFeature"] = {false},
		["DrawMaterial"] = {false},
		["DrawProjectile"] = {false},
		["DrawShield"] = {false},
		["DrawUnit"] = {false},
		["Explosion"] = {false},
		["GroupChanged"] = {false},
		["IsAbove"] = {false},
		["KeyMapChanged"] = {false},
		["KeyPress"] = {false},
		["KeyRelease"] = {false},
		["MapDrawCmd"] = {false},
		["MouseMove"] = {false},
		["MousePress"] = {false},
		["MouseWheel"] = {false},
		["MoveCtrlNotify"] = {false},
		["ResourceExcess"] = {false},
		["ShieldPreDamaged"] = {false},
		["TerraformComplete"] = {false},
		["TextEditing"] = {false},
		["TextInput"] = {false},
		["UnitFeatureCollision"] = {false},
		["UnitUnitCollision"] = {false},
		}
		local values = default[name]
		results = values and pack(unpack(values, 1, #values)) or pack()
	end
	trace(name, results, unpackn(args))
	return unpackn(results)
end

if not synced then
	function gadget:RecvFromSynced(name, encoded)
		if name == "native_api_callin_trace" then
			forward(encoded)
		elseif name == "native_api_callin_phase" then
			forward(Common.encode({ context = "callin_phase", name = encoded }))
		end
	end
end

